// useContador.js
import { ref } from 'vue';

export function useContador(inicial = 0) {
  const valor = ref(inicial);
  function incrementar() {
    valor.value++;
  }
  function reiniciar() {
    valor.value = inicial;
  }
  return { valor, incrementar, reiniciar };
}

